using System;
using System.Diagnostics.CodeAnalysis;
using Fdw.Collections;
using Fdw.Collections.Attributes;

namespace Fdw.Data.SchemaImporters.Abstractions;

/// <summary>
/// TypeCollection for schema importers.
/// Implementations use [TypeOption(typeof(SchemaImporters), "name")] and leave RestrictToCurrentCompilation unset:
/// the importers live in other assemblies than this collection, and a restricted option is registered only by
/// the collection's own assembly. An option needs a public parameterless constructor.
/// Generated by TypeCollectionGenerator with high-performance lookups.
/// </summary>
/// <ExcludedFromCoverage>Source-generated TypeCollection class</ExcludedFromCoverage>
[ExcludeFromCodeCoverage]
[TypeCollection(typeof(ISchemaImporter), typeof(ISchemaImporter), typeof(SchemaImporters))]
public abstract partial class SchemaImporters : TypeCollectionBase<ISchemaImporter>
{
    /// <summary>
    /// How long an importer waits when it only checks that a remote source answers. A deployment
    /// sets this before the host starts.
    /// </summary>
    public static TimeSpan SourceCheckTimeout { get; set; } = TimeSpan.FromSeconds(10);

    /// <summary>
    /// How long an importer waits for a remote schema document to download. A deployment sets this
    /// before the host starts.
    /// </summary>
    public static TimeSpan SourceFetchTimeout { get; set; } = TimeSpan.FromSeconds(30);
}
